const Hero = () => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setIsVisible(true), 100);
    return () => clearTimeout(timer);
  }, []);

  const scrollToTimeline = () => {
    const timeline = document.getElementById('timeline');
    if (timeline) {
      const targetPosition = timeline.offsetTop;
      const startPosition = window.pageYOffset;
      const distance = targetPosition - startPosition;
      const duration = 1000; // 1 second
      let start = null;

      const animation = (currentTime) => {
        if (start === null) start = currentTime;
        const timeElapsed = currentTime - start;
        const run = easeInOutQuad(timeElapsed, startPosition, distance, duration);
        window.scrollTo(0, run);
        if (timeElapsed < duration) requestAnimationFrame(animation);
      };

      const easeInOutQuad = (t, b, c, d) => {
        t /= d / 2;
        if (t < 1) return c / 2 * t * t + b;
        t--;
        return -c / 2 * (t * (t - 2) - 1) + b;
      };

      requestAnimationFrame(animation);
    }
  };

  return (
    <section className="relative min-h-screen flex items-center justify-center overflow-hidden bg-gradient-to-b from-sky-400 via-sky-300 to-sky-300">
      {/* Cloud background image */}
      <div
        className="absolute inset-0 bg-cover bg-center bg-no-repeat opacity-60"
        style={{ backgroundImage: 'url(/cloud-bg.jpg)' }}
      />

      {/* Rainbow - top right corner */}
      <div className="absolute -top-36 -right-40 w-[700px] h-[400px]">
        <RainbowRight className="w-full h-full" />
      </div>

      {/* Rainbow - bottom left corner */}
      <div className="absolute -bottom-20 -left-24 w-[400px] h-[300px]">
        <RainbowLeft className="w-full h-full" />
      </div>

      {/* Floating decorations */}
      <div className="absolute inset-0 pointer-events-none overflow-hidden">
        {/* Smiley faces */}
        <div className="absolute top-[15%] left-[10%] floating-element stagger-1">
          <SmileyFace size="64px" />
        </div>
        <div className="absolute top-[25%] right-[15%] floating-element stagger-2">
          <SmileyFace size="48px" />
        </div>
        <div className="absolute top-[60%] left-[8%] floating-element stagger-3">
          <SmileyFace size="80px" />
        </div>
        <div className="absolute bottom-[5%] right-[10%] floating-element stagger-4">
          <SmileyFace size="64px" />
        </div>
        <div className="absolute top-[5%] left-[45%] floating-element stagger-5">
          <SmileyFace size="48px" />
        </div>
        <div className="absolute bottom-[10%] left-[40%] floating-element stagger-1">
          <SmileyFace size="48px" />
        </div>
        <div className="absolute top-[70%] right-[25%] floating-element stagger-2">
          <SmileyFace size="64px" />
        </div>

        {/* Stars */}
        <div className="absolute top-[20%] left-[20%] floating-element stagger-2">
          <StarIcon size="32px" />
        </div>
        <div className="absolute top-[10%] left-[35%] floating-element stagger-3">
          <StarIcon size="24px" />
        </div>
        <div className="absolute top-[10%] right-[30%] floating-element stagger-1">
          <StarIcon size="48px" />
        </div>
        <div className="absolute bottom-[40%] left-[15%] floating-element stagger-4">
          <StarIcon size="24px" />
        </div>
        <div className="absolute top-[50%] right-[8%] floating-element stagger-5">
          <StarIcon size="32px" />
        </div>

        {/* Flower decorations */}
        <div className="absolute top-[40%] left-[5%] floating-element stagger-2">
          <div className="spinning-flower">
            <FlowerIcon size="80px" />
          </div>
        </div>
        <div className="absolute bottom-[25%] right-[5%] floating-element stagger-4">
          <div className="spinning-flower">
            <FlowerIcon size="80px" />
          </div>
        </div>
      </div>

      {/* Main content */}
      <div
        className={`
          relative z-10 text-center px-4
          transform transition-all duration-1000 ease-out
          ${isVisible ? 'opacity-100 scale-100' : 'opacity-0 scale-90'}
        `}
      >
        {/* Main title with retro pink style */}
        <h1 className="retro-title text-7xl sm:text-8xl md:text-9xl lg:text-[12rem] font-bold mb-6 leading-tight">
          <span className="inline-block float-word-1">YEAR</span>
          <span className="inline-block italic font-normal opacity-80 float-word-2">of</span>
          <span className="inline-block float-word-3">LOVE</span>
        </h1>

        {/* Subtitle */}
        <p className="text-black text-sm md:text-lg lg:text-2xl max-w-2xl mx-auto mb-10 leading-relaxed font-clean">
          Những khoảng khắc đẹp nhất trong hành trình yêu thương của chúng mình được lưu giữ tại đây.
        </p>

        {/* CTA Button */}
        <div className="flex justify-center">
          <button onClick={scrollToTimeline} className='let-go-button inline-flex items-center mt-20'>
            <div class="svg-wrapper-1">
              <div class="svg-wrapper">
                <svg className="w-6 h-6" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg">
                  <g>
                    <path stroke="#000000" fill="#ffffff" d="M39 20c0 10.493-8.507 19-19 19S1 30.493 1 20 9.507 1 20 1s19 8.507 19 19z"></path>
                    <path stroke="#000000" fill="#FE0E0E" d="m20.392 29.398-.095-.066a47 47 0 0 1-4.045-3.181c-1.133-1-2.284-2.132-3.204-3.286-.928-1.162-1.587-2.303-1.795-3.325l-.005-.024-.007-.024a5.55 5.55 0 0 1 .73-4.754c.62-.9 1.49-1.577 2.488-1.94a4.94 4.94 0 0 1 3.094-.095 5.14 5.14 0 0 1 2.592 1.782l.387.497.396-.49a5.1 5.1 0 0 1 3.018-1.816 4.95 4.95 0 0 1 3.428.607 5.3 5.3 0 0 1 1.933 1.996c.462.835.702 1.786.693 2.753a5.5 5.5 0 0 1-.274 1.657l-.008.023-.005.024c-.228 1.017-.909 2.144-1.858 3.286-.943 1.134-2.114 2.24-3.265 3.217a47 47 0 0 1-4.198 3.159Z"></path>
                  </g>
                </svg>
              </div>
            </div>
            <span>Let go!!!</span>
          </button>
        </div>

      </div>

      {/* Scroll indicator */}
      <button
        className="absolute bottom-8 left-1/2 transform -translate-x-1/2 text-white/80 hover:text-white transition-colors duration-300 focus:outline-none z-20"
        aria-label="Scroll to timeline"
      >
        <div className="flex flex-col items-center animate-bounce">
          <svg
            className="w-8 h-8"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M19 14l-7 7m0 0l-7-7m7 7V3"
            />
          </svg>
        </div>
      </button>

      {/* Bottom blur overlay for smooth transition */}
      <div className="absolute bottom-0 left-0 right-0 h-40 bg-gradient-to-b from-transparent via-sky-300/40 to-sky-300 backdrop-blur-md pointer-events-none" />
    </section>
  );
};

export default Hero;
